#include <stdio.h>
void hanoi(int n, char from, char to, char via) {
    if (n == 0) return;
    hanoi(n - 1, from, via, to);
    printf("%d:%c%c ", n, from, to);
    hanoi(n - 1, via, to, from);
}
int main(void) {
    hanoi(3, 'A', 'C', 'B');
    return 0;
}

#include <stdio.h>
int sd(int n) {
    if (n == 0) return 0;
    int r = n % 10 + sd(n / 10);
    printf("sd(%d)=%d ", n, r);
    return r;
}
int main(void) {
    sd(472);
    return 0;
}

