Which statement inside main() causes a compile error?

#include <stdio.h>
int sq(int n);
void hello(void);
int main(void) {
    int a = sq(3.5);
    int b = sq(2, 3);
    hello();
    sq(4);
    return 0;
}
int sq(int n) { return n * n; }
void hello(void) { printf("hi"); }

What is the output of the following program?

