Consider this recursive power function. How many calls of pw are made in total (including the first) to evaluate pw(2, 10), and what value is returned?

long pw(long x, int n) {
    if (n == 0)
        return 1;
    long h = pw(x, n / 2);
    if (n % 2 == 0)
        return h * h;
    return x * h * h;
}

For the function below, how many calls of gcd are made in total (including the first) by gcd(36, 84), and what is returned?

int gcd(int a, int b) {
    if (b == 0)
        return a;
    return gcd(b, a % b);
}

What is the output of the following program?

#include <stdio.h>
int moves = 0, calls = 0;
void hanoi(int n, char from, char to, char via) {
    calls++;
    if (n == 0)
        return;
    hanoi(n - 1, from, via, to);
    moves++;
    hanoi(n - 1, via, to, from);
}
int main(void) {
    hanoi(4, 'A', 'C', 'B');
    printf("%d %d", moves, calls);
    return 0;
}

With the function below, how many times is fib called in total (including the first call) when fib(5) is evaluated?

int fib(int n) {
    if (n < 2)
        return n;
    return fib(n - 1) + fib(n - 2);
}

The factorial function below is called as fact(0). What happens?

int fact(int n) {
    if (n == 1)
        return 1;
    return n * fact(n - 1);
}

